.style-luma {
  /* MARK: Slider */
  .cn-slider {
    @apply data-vertical:min-h-40;
  }

  .cn-slider-track {
    @apply bg-input/90 rounded-full data-horizontal:h-2 data-horizontal:w-full data-vertical:h-full data-vertical:w-2;
  }

  .cn-slider-range {
    @apply bg-primary;
  }

  .cn-slider-thumb {
    @apply ring-black/10 not-dark:bg-clip-padding ring-1 h-4 w-6 rounded-full bg-white shadow-md transition-[color,box-shadow,background-color] hover:ring-4 hover:ring-ring/30 focus-visible:ring-4 focus-visible:ring-ring/30 focus-visible:outline-hidden data-vertical:h-6 data-vertical:w-4;
  }

  /* MARK: Switch */
  .cn-switch {
    @apply data-checked:bg-primary data-unchecked:bg-input/90 data-checked:border-primary border-2 data-unchecked:border-transparent focus-visible:border-ring focus-visible:ring-ring/30 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive dark:aria-invalid:border-destructive/50 shrink-0 rounded-full focus-visible:ring-3 aria-invalid:ring-3 group-has-[:focus-visible]/field-label:ring-0 group-has-[:focus-visible]/field-label:data-unchecked:border-transparent group-has-[:focus-visible]/field-label:data-checked:border-primary data-[size=default]:h-5 data-[size=default]:w-11 data-[size=sm]:h-4 data-[size=sm]:w-7;
  }

  .cn-switch-aria {
    @apply data-selected:bg-primary not-data-selected:bg-input/90 data-selected:border-primary not-data-selected:border-transparent data-focus-visible:border-ring data-focus-visible:ring-ring/30 data-focus-visible:ring-3 data-invalid:ring-destructive/20 dark:data-invalid:ring-destructive/40 data-invalid:border-destructive dark:data-invalid:border-destructive/50 data-invalid:ring-3;
  }

  .cn-switch-thumb {
    @apply bg-background dark:data-unchecked:bg-foreground dark:data-checked:bg-primary-foreground rounded-full shadow-sm group-data-[size=default]/switch:h-4 group-data-[size=default]/switch:w-6 group-data-[size=sm]/switch:h-3 group-data-[size=sm]/switch:w-4 data-checked:translate-x-[calc(100%-8px)] data-unchecked:translate-x-0 not-dark:bg-clip-padding;
  }

  .cn-switch-thumb-aria {
    @apply dark:not-data-selected:bg-foreground dark:data-selected:bg-primary-foreground data-selected:translate-x-[calc(100%-8px)] not-data-selected:translate-x-0;
  }

  /* MARK: Radio */
  .cn-radio-group {
    @apply grid gap-3;
  }

  .cn-radio-group-item {
    @apply bg-input/90 data-checked:bg-primary data-checked:text-primary-foreground dark:data-checked:bg-primary border-transparent aria-invalid:border-destructive focus-visible:border-ring focus-visible:ring-ring/30 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 dark:aria-invalid:border-destructive/50 flex size-4 rounded-full border focus-visible:ring-3 aria-invalid:ring-3 group-has-[:focus-visible]/field-label:ring-0 group-has-[:focus-visible]/field-label:border-transparent;
  }

  .cn-radio-group-item-aria {
    @apply data-selected:bg-primary data-selected:text-primary-foreground dark:data-selected:bg-primary data-focus-visible:border-ring data-focus-visible:ring-ring/30 data-focus-visible:ring-3 data-invalid:border-destructive data-invalid:ring-destructive/20 dark:data-invalid:ring-destructive/40 dark:data-invalid:border-destructive/50 data-invalid:ring-3;
  }

  .cn-radio-group-indicator {
    @apply flex size-4 items-center justify-center;
  }

  .cn-radio-group-indicator-icon {
    @apply bg-primary-foreground absolute top-1/2 left-1/2 size-2 -translate-x-1/2 -translate-y-1/2 rounded-full dark:size-2.5;
  }

  /* MARK: Checkbox */
  .cn-checkbox {
    @apply bg-input/90 data-checked:bg-primary data-checked:text-primary-foreground dark:data-checked:bg-primary data-checked:border-primary border-transparent aria-invalid:aria-checked:border-primary aria-invalid:border-destructive dark:aria-invalid:border-destructive/50 focus-visible:border-ring focus-visible:ring-ring/30 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 flex size-4 items-center justify-center rounded-[5px] border transition-shadow group-has-disabled/field:opacity-50 focus-visible:ring-3 aria-invalid:ring-3 group-has-[:focus-visible]/field-label:ring-0 group-has-[:focus-visible]/field-label:not-data-checked:border-transparent group-has-[:focus-visible]/field-label:data-checked:border-primary;
  }

  .cn-checkbox-aria {
    @apply data-selected:bg-primary data-selected:text-primary-foreground dark:data-selected:bg-primary data-selected:border-primary data-focus-visible:border-ring data-focus-visible:ring-ring/30 data-focus-visible:ring-3 data-invalid:data-selected:border-primary data-invalid:border-destructive dark:data-invalid:border-destructive/50 data-invalid:ring-destructive/20 dark:data-invalid:ring-destructive/40 data-invalid:ring-3;
  }

  .cn-checkbox-indicator {
    @apply [&>svg]:size-3.5;
  }

  /* MARK: Button */
  .cn-button {
    @apply focus-visible:border-ring focus-visible:ring-ring/30 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive dark:aria-invalid:border-destructive/50 rounded-4xl border border-transparent bg-clip-padding text-sm font-medium focus-visible:ring-3 aria-invalid:ring-3 active:not-aria-[haspopup]:translate-y-px [&_svg:not([class*='size-'])]:size-4;
  }

  .cn-button-variant-default {
    @apply bg-primary text-primary-foreground hover:bg-primary/80;
  }

  .cn-button-variant-outline {
    @apply border-border bg-background dark:bg-transparent hover:bg-muted hover:text-foreground dark:hover:bg-input/30 aria-expanded:bg-muted aria-expanded:text-foreground;
  }

  .cn-button-variant-secondary {
    @apply bg-secondary text-secondary-foreground hover:bg-[color-mix(in_oklch,var(--secondary),var(--foreground)_5%)] aria-expanded:bg-secondary aria-expanded:text-secondary-foreground;
  }

  .cn-button-variant-ghost {
    @apply hover:bg-muted hover:text-foreground dark:hover:bg-muted/50 aria-expanded:bg-muted aria-expanded:text-foreground;
  }

  .cn-button-variant-destructive {
    @apply bg-destructive/10 hover:bg-destructive/20 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/20 text-destructive focus-visible:border-destructive/40 dark:hover:bg-destructive/30;
  }

  .cn-button-variant-link {
    @apply text-primary underline-offset-4 hover:underline;
  }

  .cn-button-size-xs {
    @apply h-6 gap-1 px-2.5 text-xs has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2 [&_svg:not([class*='size-'])]:size-3;
  }

  .cn-button-size-sm {
    @apply h-8 gap-1 px-3 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2;
  }

  .cn-button-size-default {
    @apply h-9 gap-1.5 px-3 has-data-[icon=inline-end]:pr-2.5 has-data-[icon=inline-start]:pl-2.5;
  }

  .cn-button-size-lg {
    @apply h-10 gap-1.5 px-4 has-data-[icon=inline-end]:pr-3 has-data-[icon=inline-start]:pl-3;
  }

  .cn-button-size-icon-xs {
    @apply size-6 [&_svg:not([class*='size-'])]:size-3;
  }

  .cn-button-size-icon-sm {
    @apply size-8;
  }

  .cn-button-size-icon {
    @apply size-9;
  }

  .cn-button-size-icon-lg {
    @apply size-10;
  }

  /* MARK: Button Group */
  .cn-button-group {
    @apply has-[>[data-slot=button-group]]:gap-2 has-[select[aria-hidden=true]:last-child]:[&>[data-slot=select-trigger]:last-of-type]:rounded-r-4xl has-[>[data-variant=outline]]:[&>input]:border-border has-[>[data-variant=outline]]:[&>input:focus-visible]:border-ring has-[>[data-variant=outline]]:*:data-[slot=input-group]:border-border has-[>[data-variant=outline]]:[&>[data-slot=input-group]:has(:focus-visible)]:border-ring has-[>[data-variant=outline]]:*:data-[slot=select-trigger]:border-border has-[>[data-variant=outline]]:[&>[data-slot=select-trigger]:focus-visible]:border-ring;
  }

  .cn-button-group-orientation-horizontal {
    @apply [&>[data-slot]:not(:has(~[data-slot]))]:rounded-r-4xl!;
  }

  .cn-button-group-orientation-vertical {
    @apply [&>[data-slot]:not(:has(~[data-slot]))]:rounded-b-4xl!;
  }

  .cn-button-group-text {
    @apply bg-muted gap-2 rounded-4xl border px-2.5 text-sm font-medium [&_svg:not([class*='size-'])]:size-4;
  }

  .cn-button-group-separator {
    @apply bg-input;
  }

  /* MARK: Input */
  .cn-input {
    @apply bg-input/50 border-transparent focus-visible:border-ring focus-visible:ring-ring/30 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive dark:aria-invalid:border-destructive/50 h-9 rounded-3xl border px-3 py-1 text-base transition-[color,box-shadow,background-color] file:h-7 file:text-sm file:font-medium focus-visible:ring-3 aria-invalid:ring-3 md:text-sm;
  }

  /* MARK: Textarea */
  .cn-textarea {
    @apply bg-input/50 border-transparent focus-visible:border-ring focus-visible:ring-ring/30 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive dark:aria-invalid:border-destructive/50 resize-none rounded-2xl border px-3 py-3 text-base transition-[color,box-shadow,background-color] focus-visible:ring-3 aria-invalid:ring-3 md:text-sm;
  }

  /* MARK: Select */
  .cn-select-trigger {
    @apply bg-input/50 border-transparent data-placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-ring/30 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive dark:aria-invalid:border-destructive/50 gap-1.5 rounded-3xl border py-2 px-3 text-sm transition-[color,box-shadow,background-color] focus-visible:ring-3 aria-invalid:ring-3 data-[size=default]:h-9 data-[size=sm]:h-8 *:data-[slot=select-value]:flex *:data-[slot=select-value]:gap-1.5 [&_svg:not([class*='size-'])]:size-4;
  }

  .cn-select-value {
    @apply flex flex-1 text-left;
  }

  .cn-select-value-aria {
    @apply data-placeholder:text-muted-foreground;
  }

  .cn-select-trigger-icon {
    @apply text-muted-foreground size-4;
  }

  .cn-select-content {
    @apply bg-popover text-popover-foreground data-open:animate-in data-closed:animate-out data-closed:fade-out-0 data-open:fade-in-0 data-closed:zoom-out-95 data-open:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 ring-foreground/5 dark:ring-foreground/10 min-w-36 rounded-3xl shadow-lg ring-1 duration-100;
  }

  .cn-select-content-logical {
    @apply data-[side=inline-start]:slide-in-from-right-2 data-[side=inline-end]:slide-in-from-left-2;
  }

  .cn-select-label {
    @apply text-muted-foreground px-3 py-2.5 text-xs;
  }

  .cn-select-item {
    @apply focus:bg-accent focus:text-accent-foreground not-data-[variant=destructive]:focus:**:text-accent-foreground gap-2.5 rounded-2xl py-2 pr-8 pl-3 text-sm font-medium [&_svg:not([class*='size-'])]:size-4 *:[span]:last:flex *:[span]:last:items-center *:[span]:last:gap-2;
  }

  .cn-select-item-aria {
    @apply data-focused:bg-accent data-focused:text-accent-foreground;
  }

  .cn-select-item-indicator {
    @apply pointer-events-none absolute right-2 flex size-4 items-center justify-center;
  }

  .cn-select-group {
    @apply scroll-my-1.5 p-1.5;
  }

  .cn-select-item-text {
    @apply flex flex-1 gap-2;
  }

  .cn-select-separator {
    @apply bg-border -mx-1.5 my-1.5 h-px;
  }

  .cn-select-scroll-up-button {
    @apply bg-popover z-10 flex cursor-default items-center justify-center py-1 [&_svg:not([class*='size-'])]:size-4;
  }

  .cn-select-scroll-down-button {
    @apply bg-popover z-10 flex cursor-default items-center justify-center py-1 [&_svg:not([class*='size-'])]:size-4;
  }

  .cn-select-empty-aria {
    @apply text-muted-foreground hidden w-full justify-center py-2 text-center text-sm group-data-empty/select-list:flex;
  }

  /* MARK: Native Select */
  .cn-native-select {
    @apply bg-input/50 border-transparent placeholder:text-muted-foreground selection:bg-primary selection:text-primary-foreground focus-visible:border-ring focus-visible:ring-ring/30 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive dark:aria-invalid:border-destructive/50 h-9 w-full min-w-0 appearance-none rounded-3xl border py-1 pr-8 pl-3 text-sm transition-[color,box-shadow,background-color] select-none focus-visible:ring-3 aria-invalid:ring-3 data-[size=sm]:h-8;
  }

  .cn-native-select-icon {
    @apply text-muted-foreground top-1/2 right-2.5 size-4 -translate-y-1/2;
  }

  /* MARK: Combobox */
  .cn-combobox-content {
    @apply bg-popover text-popover-foreground data-open:animate-in data-closed:animate-out data-closed:fade-out-0 data-open:fade-in-0 data-closed:zoom-out-95 data-open:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 ring-foreground/5 dark:ring-foreground/10 *:data-[slot=input-group]:bg-input/50 *:data-[slot=input-group]:border-input/30 max-h-72 min-w-36 overflow-hidden rounded-3xl shadow-lg ring-1 duration-100 *:data-[slot=input-group]:m-1.5 *:data-[slot=input-group]:mb-0 *:data-[slot=input-group]:h-8 *:data-[slot=input-group]:shadow-none;
  }

  .cn-combobox-content-logical {
    @apply data-[side=inline-start]:slide-in-from-right-2 data-[side=inline-end]:slide-in-from-left-2;
  }

  .cn-combobox-label {
    @apply text-muted-foreground px-3 py-2.5 text-xs;
  }

  .cn-combobox-item {
    @apply data-highlighted:bg-accent data-highlighted:text-accent-foreground not-data-[variant=destructive]:data-highlighted:**:text-accent-foreground gap-2.5 rounded-2xl py-2 pr-8 pl-3 text-sm font-medium [&_svg:not([class*='size-'])]:size-4;
  }

  .cn-combobox-item-aria {
    @apply data-focused:bg-accent data-focused:text-accent-foreground not-data-[variant=destructive]:data-focused:**:text-accent-foreground;
  }

  .cn-combobox-item-indicator {
    @apply pointer-events-none absolute right-2 flex size-4 items-center justify-center;
  }

  .cn-combobox-empty {
    @apply text-muted-foreground hidden w-full justify-center py-2 text-center text-sm group-data-empty/combobox-content:flex;
  }

  .cn-combobox-list {
    @apply no-scrollbar max-h-[min(calc(--spacing(72)---spacing(9)),calc(var(--available-height)---spacing(9)))] scroll-py-1.5 overflow-y-auto p-1.5 data-empty:p-0;
  }

  .cn-combobox-item-text {
    @apply flex flex-1 gap-2;
  }

  .cn-combobox-separator {
    @apply bg-border -mx-1.5 my-1.5 h-px;
  }

  .cn-combobox-trigger {
    @apply [&_svg:not([class*='size-'])]:size-4;
  }

  .cn-combobox-trigger-icon {
    @apply text-muted-foreground size-4;
  }

  .cn-combobox-chips {
    @apply bg-input/50 border-transparent focus-within:border-ring focus-within:ring-ring/30 has-aria-invalid:ring-destructive/20 dark:has-aria-invalid:ring-destructive/40 has-aria-invalid:border-destructive dark:has-aria-invalid:border-destructive/50 flex min-h-9 flex-wrap items-center gap-1.5 rounded-3xl border bg-clip-padding px-3 py-1.5 text-sm transition-[color,box-shadow,background-color] focus-within:ring-3 has-aria-invalid:ring-3 has-data-[slot=combobox-chip]:px-1.5;
  }

  .cn-combobox-chip {
    @apply bg-input text-foreground flex h-[calc(--spacing(5.5))] w-fit items-center justify-center gap-1 rounded-3xl px-2 text-xs font-medium whitespace-nowrap has-data-[slot=combobox-chip-remove]:pr-0 dark:bg-input/60;
  }

  .cn-combobox-chip-remove {
    @apply -ml-1 opacity-50 hover:opacity-100;
  }

  /* MARK: Input Group */
  .cn-input-group {
    @apply bg-input/50 border-transparent has-[[data-slot=input-group-control]:focus-visible]:border-ring has-[[data-slot=input-group-control]:focus-visible]:ring-ring/30 has-[[data-slot][aria-invalid=true]]:ring-destructive/20 has-[[data-slot][aria-invalid=true]]:border-destructive dark:has-[[data-slot][aria-invalid=true]]:ring-destructive/40 h-9 rounded-4xl border transition-[color,box-shadow,background-color] in-data-[slot=combobox-content]:focus-within:border-inherit in-data-[slot=combobox-content]:focus-within:ring-0 has-data-[align=block-end]:rounded-3xl has-data-[align=block-start]:rounded-3xl has-[[data-slot=input-group-control]:focus-visible]:ring-3 has-[[data-slot][aria-invalid=true]]:ring-3 has-[textarea]:rounded-2xl has-[>[data-align=block-end]]:h-auto has-[>[data-align=block-end]]:flex-col has-[>[data-align=block-start]]:h-auto has-[>[data-align=block-start]]:flex-col has-[>[data-align=block-end]]:[&>input]:pt-3 has-[>[data-align=block-start]]:[&>input]:pb-3 has-[>[data-align=inline-end]]:[&>input]:pr-1.5 has-[>[data-align=inline-start]]:[&>input]:pl-1.5;
  }

  .cn-input-group-addon {
    @apply text-muted-foreground **:data-[slot=kbd]:bg-muted-foreground/10 h-auto gap-2 py-2 text-sm font-medium group-data-[disabled=true]/input-group:opacity-50 **:data-[slot=kbd]:rounded-3xl **:data-[slot=kbd]:px-1.5 [&>svg:not([class*='size-'])]:size-4;
  }

  .cn-input-group-addon-align-inline-start {
    @apply pl-3 has-[>button]:-ml-1 has-[>kbd]:-ml-1;
  }

  .cn-input-group-addon-align-inline-end {
    @apply pr-3 has-[>button]:-mr-1 has-[>kbd]:-mr-1;
  }

  .cn-input-group-addon-align-block-start {
    @apply px-3 pt-3 group-has-[>input]/input-group:pt-3.5 [.border-b]:pb-3.5;
  }

  .cn-input-group-addon-align-block-end {
    @apply px-3 pb-3 group-has-[>input]/input-group:pb-3.5 [.border-t]:pt-3.5;
  }

  .cn-input-group-button {
    @apply gap-2 rounded-4xl text-sm;
  }

  .cn-input-group-button-size-xs {
    @apply h-6 gap-1 rounded-xl px-1.5 [&>svg:not([class*='size-'])]:size-3.5;
  }

  .cn-input-group-button-size-icon-xs {
    @apply size-6 rounded-xl p-0 has-[>svg]:p-0;
  }

  .cn-input-group-button-size-icon-sm {
    @apply size-8 p-0 has-[>svg]:p-0;
  }

  .cn-input-group-text {
    @apply text-muted-foreground gap-2 text-sm [&_svg:not([class*='size-'])]:size-4;
  }

  .cn-input-group-input {
    @apply rounded-none border-0 bg-transparent shadow-none ring-0 focus-visible:ring-0 aria-invalid:ring-0 dark:bg-transparent;
  }

  .cn-input-group-textarea {
    @apply rounded-none border-0 bg-transparent py-2.5 shadow-none ring-0 focus-visible:ring-0 aria-invalid:ring-0 dark:bg-transparent;
  }

  /* MARK: Input OTP */
  .cn-input-otp {
    @apply gap-2;
  }

  .cn-input-otp-group {
    @apply has-aria-invalid:ring-destructive/20 dark:has-aria-invalid:ring-destructive/40 has-aria-invalid:border-destructive rounded-3xl has-aria-invalid:ring-3;
  }

  .cn-input-otp-slot {
    @apply bg-input/50 border-input data-[active=true]:border-ring data-[active=true]:ring-ring/30 data-[active=true]:aria-invalid:ring-destructive/20 dark:data-[active=true]:aria-invalid:ring-destructive/40 aria-invalid:border-destructive size-9 border-y border-r text-sm transition-all outline-none first:rounded-l-3xl first:border-l last:rounded-r-3xl data-[active=true]:ring-3;
  }

  .cn-input-otp-caret-line {
    @apply animate-caret-blink bg-foreground h-4 w-px duration-1000;
  }

  .cn-input-otp-separator {
    @apply [&_svg:not([class*='size-'])]:size-4;
  }

  /* MARK: Field */
  .cn-field-set {
    @apply gap-6 has-[>[data-slot=checkbox-group]]:gap-3 has-[>[data-slot=radio-group]]:gap-3;
  }

  .cn-field-legend {
    @apply mb-3 font-medium data-[variant=label]:text-sm data-[variant=legend]:text-base;
  }

  .cn-field-group {
    @apply gap-7 data-[slot=checkbox-group]:gap-3 *:data-[slot=field-group]:gap-4;
  }

  .cn-field {
    @apply data-[invalid=true]:text-destructive gap-3;
  }

  .cn-field-content {
    @apply gap-1;
  }

  .cn-field-label {
    @apply has-data-checked:bg-input/30 gap-2 leading-snug group-data-[disabled=true]/field:opacity-50 has-[>[data-slot=field]]:rounded-2xl has-[>[data-slot=field]]:border has-[>[data-slot=field]]:not-has-[:disabled,[data-disabled]]:hover:bg-input/40 has-[>[data-slot=field]]:has-[:focus-visible]:border-ring has-[>[data-slot=field]]:has-[:focus-visible]:ring-ring/50 has-[>[data-slot=field]]:has-[:focus-visible]:ring-3 *:data-[slot=field]:p-4;
  }

  .cn-field-label-aria {
    @apply has-data-selected:bg-input/30;
  }

  .cn-field-title {
    @apply gap-2 leading-snug text-sm font-medium group-data-[disabled=true]/field:opacity-50;
  }

  .cn-field-description {
    @apply text-muted-foreground text-left text-sm [[data-variant=legend]+&]:-mt-1.5;
  }

  .cn-field-separator {
    @apply -my-2 h-5 text-sm group-data-[variant=outline]/field-group:-mb-2;
  }

  .cn-field-separator-content {
    @apply text-muted-foreground px-2;
  }

  .cn-field-error {
    @apply text-destructive text-sm;
  }

  /* MARK: Tabs */
  .cn-tabs {
    @apply gap-2;
  }

  .cn-tabs-list {
    @apply rounded-full p-1 group-data-horizontal/tabs:h-9 group-data-vertical/tabs:rounded-2xl data-[variant=line]:rounded-none;
  }

  .cn-tabs-trigger {
    @apply gap-2 rounded-full border border-transparent! px-3 py-1 text-sm font-medium group-data-vertical/tabs:px-3 group-data-vertical/tabs:py-1.5 group-data-vertical/tabs:rounded-2xl [&_svg:not([class*='size-'])]:size-4 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2;
  }

  .cn-tabs-content {
    @apply text-sm;
  }

  /* MARK: Card */
  .cn-card {
